# 🛒 Plantilla Universal de E-commerce Open Source (Full Stack)

A continuación te presento una **plantilla original** inspirada en las mejores prácticas de los proyectos open source más completos del mundo (Medusa.js, Saleor, WooCommerce, Spree Commerce, Vendure) pero reescrita con arquitectura moderna, tipada y escalable.

> ⚠️ **Nota:** No transcribo literalmente código de proyectos existentes (protegido por copyright). En su lugar, construyo una plantilla original con patrones probados de la industria, lista para producción.

---

## 📐 1. Arquitectura propuesta

```
┌─────────────┐     ┌──────────────┐     ┌──────────────┐
│  Next.js 14 │────▶│  NestJS API  │────▶│  PostgreSQL  │
│  (Frontend) │     │  (Backend)   │     │   + Prisma   │
└─────────────┘     └──────┬───────┘     └──────────────┘
                           │
        ┌──────────────────┼──────────────────┐
        ▼                  ▼                  ▼
   ┌─────────┐      ┌──────────┐      ┌────────────┐
   │  Redis  │      │  Stripe  │      │ Meilisearch│
   │ (cache) │      │ (pagos)  │      │  (search)  │
   └─────────┘      └──────────┘      └────────────┘
```

---

## 📁 2. Estructura del monorepo

```
ecommerce-universal/
├── apps/
│   ├── web/              # Next.js 14 (frontend)
│   └── api/              # NestJS (backend)
├── packages/
│   ├── ui/               # Componentes compartidos
│   ├── config/           # ESLint, TS, Tailwind
│   └── types/            # Tipos compartidos
├── docker-compose.yml
├── turbo.json
└── package.json
```

---

## 🗄️ 3. Backend — NestJS + Prisma

### `apps/api/prisma/schema.prisma`

```prisma
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

enum Role {
  CUSTOMER
  ADMIN
  VENDOR
}

enum OrderStatus {
  PENDING
  PAID
  PROCESSING
  SHIPPED
  DELIVERED
  CANCELLED
  REFUNDED
}

enum PaymentStatus {
  PENDING
  SUCCEEDED
  FAILED
  REFUNDED
}

model User {
  id            String    @id @default(cuid())
  email         String    @unique
  passwordHash  String
  firstName     String?
  lastName      String?
  phone         String?
  role          Role      @default(CUSTOMER)
  emailVerified Boolean   @default(false)
  createdAt     DateTime  @default(now())
  updatedAt     DateTime  @updatedAt

  addresses     Address[]
  orders        Order[]
  wishlist      WishlistItem[]
  reviews       Review[]
  cart          Cart?
}

model Address {
  id         String  @id @default(cuid())
  userId     String
  user       User    @relation(fields: [userId], references: [id], onDelete: Cascade)
  firstName  String
  lastName   String
  line1      String
  line2      String?
  city       String
  state      String?
  postalCode String
  country    String
  phone      String
  isDefault  Boolean @default(false)
}

model Category {
  id        String     @id @default(cuid())
  name      String
  slug      String     @unique
  parentId  String?
  parent    Category?  @relation("CategoryTree", fields: [parentId], references: [id])
  children  Category[] @relation("CategoryTree")
  products  Product[]
  createdAt DateTime   @default(now())
}

model Product {
  id          String          @id @default(cuid())
  name        String
  slug        String          @unique
  description String?
  price       Decimal         @db.Decimal(12, 2)
  compareAt   Decimal?        @db.Decimal(12, 2)
  cost        Decimal?        @db.Decimal(12, 2)
  sku         String          @unique
  stock       Int             @default(0)
  trackStock  Boolean         @default(true)
  active      Boolean         @default(true)
  featured    Boolean         @default(false)
  categoryId  String?
  category    Category?       @relation(fields: [categoryId], references: [id])
  variants    ProductVariant[]
  images      ProductImage[]
  attributes  ProductAttribute[]
  reviews     Review[]
  createdAt   DateTime        @default(now())
  updatedAt   DateTime        @updatedAt

  @@index([slug])
  @@index([categoryId])
}

model ProductVariant {
  id        String  @id @default(cuid())
  productId String
  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)
  name      String
  sku       String  @unique
  price     Decimal @db.Decimal(12, 2)
  stock     Int     @default(0)
  options   Json    // { "color": "red", "size": "M" }
}

model ProductImage {
  id        String  @id @default(cuid())
  productId String
  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)
  url       String
  alt       String?
  position  Int     @default(0)
}

model ProductAttribute {
  id        String  @id @default(cuid())
  productId String
  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)
  key       String
  value     String
}

model Cart {
  id        String     @id @default(cuid())
  userId    String?    @unique
  sessionId String?    @unique
  items     CartItem[]
  couponId  String?
  createdAt DateTime   @default(now())
  updatedAt DateTime   @updatedAt
}

model CartItem {
  id        String  @id @default(cuid())
  cartId    String
  cart      Cart    @relation(fields: [cartId], references: [id], onDelete: Cascade)
  productId String
  variantId String?
  quantity  Int     @default(1)
}

model Order {
  id              String        @id @default(cuid())
  orderNumber     String        @unique
  userId          String
  user            User          @relation(fields: [userId], references: [id])
  status          OrderStatus   @default(PENDING)
  paymentStatus   PaymentStatus @default(PENDING)
  subtotal        Decimal       @db.Decimal(12, 2)
  tax             Decimal       @db.Decimal(12, 2)
  shipping        Decimal       @db.Decimal(12, 2)
  discount        Decimal       @default(0) @db.Decimal(12, 2)
  total           Decimal       @db.Decimal(12, 2)
  currency        String        @default("USD")
  shippingAddress Json
  billingAddress  Json?
  stripePaymentId String?
  items           OrderItem[]
  createdAt       DateTime      @default(now())
  updatedAt       DateTime      @updatedAt
}

model OrderItem {
  id        String  @id @default(cuid())
  orderId   String
  order     Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)
  productId String
  variantId String?
  name      String
  sku       String
  quantity  Int
  price     Decimal @db.Decimal(12, 2)
}

model Coupon {
  id          String   @id @default(cuid())
  code        String   @unique
  type        String   // "percent" | "fixed"
  value       Decimal  @db.Decimal(12, 2)
  minOrder    Decimal? @db.Decimal(12, 2)
  maxUses     Int?
  usedCount   Int      @default(0)
  expiresAt   DateTime?
  active      Boolean  @default(true)
}

model Review {
  id        String   @id @default(cuid())
  userId    String
  user      User     @relation(fields: [userId], references: [id])
  productId String
  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)
  rating    Int
  title     String?
  comment   String?
  approved  Boolean  @default(false)
  createdAt DateTime @default(now())
}

model WishlistItem {
  id        String   @id @default(cuid())
  userId    String
  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)
  productId String
  createdAt DateTime @default(now())

  @@unique([userId, productId])
}
```

### `apps/api/src/main.ts`

```ts
import { NestFactory } from '@nestjs/core';
import { ValidationPipe, Logger } from '@nestjs/common';
import { AppModule } from './app.module';
import helmet from 'helmet';
import * as compression from 'compression';

async function bootstrap() {
  const app = await NestFactory.create(AppModule, {
    logger: ['error', 'warn', 'log'],
  });

  app.use(helmet());
  app.use(compression());
  app.enableCors({
    origin: process.env.FRONTEND_URL || 'http://localhost:3000',
    credentials: true,
  });

  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      forbidNonWhitelisted: true,
      transform: true,
    }),
  );

  const port = process.env.PORT || 4000;
  await app.listen(port);
  new Logger('Bootstrap').log(`🚀 API running on http://localhost:${port}`);
}
bootstrap();
```

