### `apps/api/src/products/products.service.ts`

```ts
import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateProductDto } from './dto/create-product.dto';
import { UpdateProductDto } from './dto/update-product.dto';
import { QueryProductDto } from './dto/query-product.dto';
import { SearchService } from '../search/search.service';
import { CacheService } from '../cache/cache.service';

@Injectable()
export class ProductsService {
  constructor(
    private prisma: PrismaService,
    private search: SearchService,
    private cache: CacheService,
  ) {}

  async findAll(query: QueryProductDto) {
    const {
      page = 1,
      limit = 20,
      category,
      minPrice,
      maxPrice,
      sort = 'createdAt',
      order = 'desc',
      search: q,
    } = query;

    const cacheKey = `products:${JSON.stringify(query)}`;
    const cached = await this.cache.get(cacheKey);
    if (cached) return cached;

    const where: any = { active: true };
    if (category) where.category = { slug: category };
    if (minPrice || maxPrice) {
      where.price = {};
      if (minPrice) where.price.gte = Number(minPrice);
      if (maxPrice) where.price.lte = Number(maxPrice);
    }
    if (q) where.name = { contains: q, mode: 'insensitive' };

    const [items, total] = await Promise.all([
      this.prisma.product.findMany({
        where,
        include: {
          images: { orderBy: { position: 'asc' } },
          category: true,
          variants: true,
        },
        orderBy: { [sort]: order },
        skip: (page - 1) * limit,
        take: limit,
      }),
      this.prisma.product.count({ where }),
    ]);

    const result = {
      items,
      total,
      page,
      limit,
      totalPages: Math.ceil(total / limit),
    };

    await this.cache.set(cacheKey, result, 60);
    return result;
  }

  async findBySlug(slug: string) {
    const product = await this.prisma.product.findUnique({
      where: { slug },
      include: {
        images: { orderBy: { position: 'asc' } },
        category: true,
        variants: true,
        attributes: true,
        reviews: { where: { approved: true }, take: 10 },
      },
    });
    if (!product) throw new NotFoundException('Producto no encontrado');
    return product;
  }

  async create(dto: CreateProductDto) {
    const product = await this.prisma.product.create({
      data: {
        ...dto,
        price: dto.price,
        variants: dto.variants
          ? { create: dto.variants }
          : undefined,
        images: dto.images
          ? { create: dto.images.map((url, i) => ({ url, position: i })) }
          : undefined,
      },
      include: { variants: true, images: true },
    });
    await this.search.indexProduct(product);
    return product;
  }

  async update(id: string, dto: UpdateProductDto) {
    const product = await this.prisma.product.update({
      where: { id },
      data: dto,
    });
    await this.search.indexProduct(product);
    return product;
  }

  async remove(id: string) {
    await this.prisma.product.update({
      where: { id },
      data: { active: false },
    });
    await this.search.removeProduct(id);
  }
}
```

### `apps/api/src/products/products.controller.ts`

```ts
import {
  Controller, Get, Post, Put, Delete,
  Param, Body, Query, UseGuards,
} from '@nestjs/common';
import { ProductsService } from './products.service';
import { CreateProductDto } from './dto/create-product.dto';
import { UpdateProductDto } from './dto/update-product.dto';
import { QueryProductDto } from './dto/query-product.dto';
import { RolesGuard } from '../auth/guards/roles.guard';
import { Roles } from '../auth/decorators/roles.decorator';
import { Role } from '@prisma/client';

@Controller('products')
export class ProductsController {
  constructor(private readonly svc: ProductsService) {}

  @Get()
  findAll(@Query() q: QueryProductDto) {
    return this.svc.findAll(q);
  }

  @Get(':slug')
  findOne(@Param('slug') slug: string) {
    return this.svc.findBySlug(slug);
  }

  @Post()
  @UseGuards(RolesGuard)
  @Roles(Role.ADMIN)
  create(@Body() dto: CreateProductDto) {
    return this.svc.create(dto);
  }

  @Put(':id')
  @UseGuards(RolesGuard)
  @Roles(Role.ADMIN)
  update(@Param('id') id: string, @Body() dto: UpdateProductDto) {
    return this.svc.update(id, dto);
  }

  @Delete(':id')
  @UseGuards(RolesGuard)
  @Roles(Role.ADMIN)
  remove(@Param('id') id: string) {
    return this.svc.remove(id);
  }
}
```

### `apps/api/src/auth/auth.service.ts`

```ts
import {
  Injectable, UnauthorizedException, ConflictException,
} from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import * as bcrypt from 'bcrypt';
import { PrismaService } from '../prisma/prisma.service';
import { RegisterDto } from './dto/register.dto';
import { LoginDto } from './dto/login.dto';

@Injectable()
export class AuthService {
  constructor(
    private prisma: PrismaService,
    private jwt: JwtService,
  ) {}

  async register(dto: RegisterDto) {
    const exists = await this.prisma.user.findUnique({
      where: { email: dto.email },
    });
    if (exists) throw new ConflictException('Email ya registrado');

    const passwordHash = await bcrypt.hash(dto.password, 12);
    const user = await this.prisma.user.create({
      data: {
        email: dto.email,
        passwordHash,
        firstName: dto.firstName,
        lastName: dto.lastName,
      },
    });

    const token = this.signToken(user.id, user.role);
    return { user: this.sanitize(user), token };
  }

  async login(dto: LoginDto) {
    const user = await this.prisma.user.findUnique({
      where: { email: dto.email },
    });
    if (!user) throw new UnauthorizedException('Credenciales inválidas');

    const valid = await bcrypt.compare(dto.password, user.passwordHash);
    if (!valid) throw new UnauthorizedException('Credenciales inválidas');

    const token = this.signToken(user.id, user.role);
    return { user: this.sanitize(user), token };
  }

  private signToken(userId: string, role: string) {
    return this.jwt.sign(
      { sub: userId, role },
      { expiresIn: '7d' },
    );
  }

  private sanitize(user: any) {
    const { passwordHash, ...rest } = user;
    return rest;
  }
}
```

### `apps/api/src/payments/stripe.service.ts`

```ts
import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import Stripe from 'stripe';
import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class StripeService {
  private stripe: Stripe;

  constructor(
    private config: ConfigService,
    private prisma: PrismaService,
  ) {
    this.stripe = new Stripe(config.get('STRIPE_SECRET_KEY')!, {
      apiVersion: '2024-06-20',
    });
  }

  async createCheckoutSession(orderId: string) {
    const order = await this.prisma.order.findUnique({
      where: { id: orderId },
      include: { items: true },
    });
    if (!order) throw new Error('Orden no encontrada');

    const session = await this.stripe.checkout.sessions.create({
      mode: 'payment',
      payment_method_types: ['card'],
      line_items: order.items.map((item) => ({
        price_data: {
          currency: order.currency.toLowerCase(),
          product_data: { name: item.name },
          unit_amount: Number(item.price) * 100,
        },
        quantity: item.quantity,
      })),
      success_url: `${this.config.get('FRONTEND_URL')}/order/${orderId}/success`,
      cancel_url: `${this.config.get('FRONTEND_URL')}/order/${orderId}/cancel`,
      metadata: { orderId },
    });

    await this.prisma.order.update({
      where: { id: orderId },
      data: { stripePaymentId: session.id },
    });

    return { url: session.url };
  }

  async handleWebhook(signature: string, rawBody: Buffer) {
    const event = this.stripe.webhooks.constructEvent(
      rawBody,
      signature,
      this.config.get('STRIPE_WEBHOOK_SECRET')!,
    );

    if (event.type === 'checkout.session.completed') {
      const session = event.data.object as Stripe.Checkout.Session;
      const orderId = session.metadata?.orderId;
      if (orderId) {
        await this.prisma.order.update({
          where: { id: orderId },
          data: {
            status: 'PAID',
            paymentStatus: 'SUCCEEDED',
          },
        });
      }
    }
    return { received: true };
  }
}
```

### `apps/api/src/orders/orders.service.ts`

```ts
import { Injectable, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreateOrderDto } from './dto/create-order.dto';

@Injectable()
export class OrdersService {
  constructor(private prisma: PrismaService) {}

  async create(userId: string, dto: CreateOrderDto) {
    return this.prisma.$transaction(async (tx) => {
      const cart = await tx.cart.findUnique({
        where: { userId },
        include: { items: true },
      });
      if (!cart || cart.items.length === 0) {
        throw new BadRequestException('Carrito vacío');
      }

      let subtotal = 0;
      const orderItems = [];

      for (const item of cart.items) {
        const product = await tx.product.findUnique({
          where: { id: item.productId },
        });
        if (!product || !product.active) {
          throw new BadRequestException(`Producto no disponible: ${item.productId}`);
        }
        if (product.trackStock && product.stock < item.quantity) {
          throw new BadRequestException(`Stock insuficiente: ${product.name}`);
        }

        const price = product.price;
        subtotal += Number(price) * item.quantity;
        orderItems.push({
          productId: product.id,
          variantId: item.variantId,
          name: product.name,
          sku: product.sku,
          quantity: item.quantity,
          price,
        });

        if (product.trackStock) {
          await tx.product.update({
            where: { id: product.id },
            data: { stock: { decrement: item.quantity } },
          });
        }
      }

      const tax = subtotal * 0.16;
      const shipping = subtotal > 100 ? 0 : 9.99;
      const discount = dto.couponId ? await this.applyCoupon(tx, dto.couponId, subtotal) : 0;
      const total = subtotal + tax + shipping - discount;

      const order = await tx.order.create({
        data: {
          orderNumber: this.generateOrderNumber(),
          userId,
          subtotal,
          tax,
          shipping,
          discount,
          total,
          shippingAddress: dto.shippingAddress,
          billingAddress: dto.billingAddress,
          items: { create: orderItems },
        },
      });

      await tx.cart.update({
        where: { userId },
        data: { items: { deleteMany: {} } },
      });

      return order;
    });
  }

  private generateOrderNumber() {
    const date = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    const rand = Math.floor(Math.random() * 10000).toString().padStart(4, '0');
    return `ORD-${date}-${rand}`;
  }

  private async applyCoupon(tx: any, code: string, subtotal: number) {
    const coupon = await tx.coupon.findUnique({ where: { code } });
    if (!coupon || !coupon.active) return 0;
    if (coupon.expiresAt && coupon.expiresAt < new Date()) return 0;
    if (coupon.minOrder && subtotal < Number(coupon.minOrder)) return 0;
    if (coupon.maxUses && coupon.usedCount >= coupon.maxUses) return 0;

    let discount = 0;
    if (coupon.type === 'percent') {
      discount = (subtotal * Number(coupon.value)) / 100;
    } else {
      discount = Number(coupon.value);
    }
    await tx.coupon.update({
      where: { id: coupon.id },
      data: { usedCount: { increment: 1 } },
    });
    return discount;
  }
}
```

