```ts
import axios from 'axios';

export const api = axios.create({
  baseURL: process.env.NEXT_PUBLIC_API_URL || 'http://localhost:4000',
  withCredentials: true,
});

api.interceptors.request.use((config) => {
  if (typeof window !== 'undefined') {
    const token = localStorage.getItem('token');
    if (token) config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

api.interceptors.response.use(
  (r) => r,
  (err) => {
    if (err.response?.status === 401) {
      localStorage.removeItem('token');
      window.location.href = '/login';
    }
    return Promise.reject(err);
  },
);
```

### `apps/web/src/store/cart.ts`

```ts
import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { api } from '@/lib/api';

type CartItem = {
  id: string;
  productId: string;
  variantId?: string;
  name: string;
  image: string;
  price: number;
  quantity: number;
};

type CartState = {
  items: CartItem[];
  loading: boolean;
  addItem: (item: Omit<CartItem, 'id'>) => Promise<void>;
  updateQty: (id: string, qty: number) => void;
  removeItem: (id: string) => void;
  clear: () => void;
  fetch: () => Promise<void>;
  subtotal: () => number;
};

export const useCart = create<CartState>()(
  persist(
    (set, get) => ({
      items: [],
      loading: false,

      addItem: async (item) => {
        set({ loading: true });
        try {
          await api.post('/cart/items', item);
          set((s) => {
            const existing = s.items.find(
              (i) => i.productId === item.productId && i.variantId === item.variantId,
            );
            if (existing) {
              return {
                items: s.items.map((i) =>
                  i === existing ? { ...i, quantity: i.quantity + item.quantity } : i,
                ),
              };
            }
            return { items: [...s.items, { ...item, id: crypto.randomUUID() }] };
          });
        } finally {
          set({ loading: false });
        }
      },

      updateQty: (id, qty) => {
        api.put(`/cart/items/${id}`, { quantity: qty });
        set((s) => ({
          items: s.items.map((i) => (i.id === id ? { ...i, quantity: qty } : i)),
        }));
      },

      removeItem: (id) => {
        api.delete(`/cart/items/${id}`);
        set((s) => ({ items: s.items.filter((i) => i.id !== id) }));
      },

      clear: () => {
        api.delete('/cart');
        set({ items: [] });
      },

      fetch: async () => {
        const { data } = await api.get('/cart');
        set({ items: data.items || [] });
      },

      subtotal: () =>
        get().items.reduce((sum, i) => sum + i.price * i.quantity, 0),
    }),
    { name: 'cart-storage' },
  ),
);
```

