## 🗄️ 1. Base de Datos Universal (Prisma)

### `apps/api/prisma/schema.prisma`

```prisma
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

// ═══════════════════════════════════════════
// ENUMS
// ═══════════════════════════════════════════
enum Role          { CUSTOMER  VENDOR  ADMIN  SUPPORT }
enum OrderStatus   { PENDING  CONFIRMED  PAID  PROCESSING  SHIPPED  DELIVERED  CANCELLED  REFUNDED }
enum PaymentStatus { PENDING  AUTHORIZED  SUCCEEDED  FAILED  REFUNDED }
enum DiscountType  { PERCENT  FIXED  FREE_SHIPPING }
enum Locale        { en  es  fr  de  pt  it  zh  ja }
enum Currency      { USD  EUR  GBP  MXN  COP  ARS  BRL  CLP  PEN }

// ═══════════════════════════════════════════
// USUARIOS Y AUTENTICACIÓN
// ═══════════════════════════════════════════
model User {
  id             String    @id @default(cuid())
  email          String    @unique
  passwordHash   String
  firstName      String?
  lastName       String?
  phone          String?
  avatar         String?
  role           Role      @default(CUSTOMER)
  locale         Locale    @default(en)
  currency       Currency  @default(USD)
  emailVerified  Boolean   @default(false)
  twoFactorEnabled Boolean @default(false)
  twoFactorSecret  String?
  isActive       Boolean   @default(true)
  lastLoginAt    DateTime?
  createdAt      DateTime  @default(now())
  updatedAt      DateTime  @updatedAt

  addresses      Address[]
  orders         Order[]
  wishlist       WishlistItem[]
  reviews        Review[]
  cart           Cart?
  vendor         Vendor?
  sessions       Session[]

  @@index([email])
  @@index([role])
}

model Session {
  id         String   @id @default(cuid())
  userId     String
  user       User     @relation(fields: [userId], references: [id], onDelete: Cascade)
  token      String   @unique
  userAgent  String?
  ip         String?
  expiresAt  DateTime
  createdAt  DateTime @default(now())

  @@index([userId])
  @@index([token])
}

// ═══════════════════════════════════════════
// MARKETPLACE (MULTI-VENDOR)
// ═══════════════════════════════════════════
model Vendor {
  id              String   @id @default(cuid())
  userId          String   @unique
  user            User     @relation(fields: [userId], references: [id])
  name            String
  slug            String   @unique
  description     String?
  logo            String?
  banner          String?
  commissionRate  Decimal  @default(10) @db.Decimal(5, 2) // % para la plataforma
  payoutAccount   Json?    // Stripe Connect account ID
  rating          Decimal  @default(0) @db.Decimal(3, 2)
  reviewCount     Int      @default(0)
  isActive        Boolean  @default(true)
  createdAt       DateTime @default(now())

  products        Product[]
  orders          Order[]
  payouts         Payout[]

  @@index([slug])
}

model Payout {
  id          String   @id @default(cuid())
  vendorId    String
  vendor      Vendor   @relation(fields: [vendorId], references: [id])
  amount      Decimal  @db.Decimal(12, 2)
  currency    Currency @default(USD)
  status      String   @default("pending") // pending, paid, failed
  paidAt      DateTime?
  createdAt   DateTime @default(now())
}

// ═══════════════════════════════════════════
// CATÁLOGO
// ═══════════════════════════════════════════
model Category {
  id          String     @id @default(cuid())
  parentId    String?
  parent      Category?  @relation("CategoryTree", fields: [parentId], references: [id])
  children    Category[] @relation("CategoryTree")
  position    Int        @default(0)
  isActive    Boolean    @default(true)
  createdAt   DateTime   @default(now())

  translations CategoryTranslation[]
  products    Product[]

  @@index([parentId])
}

model CategoryTranslation {
  id          String   @id @default(cuid())
  categoryId  String
  category    Category @relation(fields: [categoryId], references: [id], onDelete: Cascade)
  locale      Locale
  name        String
  slug        String
  description String?

  @@unique([categoryId, locale])
  @@index([slug])
}

model Product {
  id            String          @id @default(cuid())
  vendorId      String?
  vendor        Vendor?         @relation(fields: [vendorId], references: [id])
  sku           String          @unique
  barcode       String?         @unique
  basePrice     Decimal         @db.Decimal(12, 2) // precio en moneda base (USD)
  cost          Decimal?        @db.Decimal(12, 2)
  stock         Int             @default(0)
  trackStock    Boolean         @default(true)
  isActive      Boolean         @default(true)
  isFeatured    Boolean         @default(false)
  isNew         Boolean         @default(false)
  weight        Decimal?        @db.Decimal(8, 3)
  categoryId    String?
  category      Category?       @relation(fields: [categoryId], references: [id])
  createdAt     DateTime        @default(now())
  updatedAt     DateTime        @updatedAt

  translations  ProductTranslation[]
  variants      ProductVariant[]
  images        ProductImage[]
  attributes    ProductAttribute[]
  tags          ProductTag[]
  reviews       Review[]
  orderItems    OrderItem[]
  wishlist      WishlistItem[]

  @@index([vendorId])
  @@index([categoryId])
  @@index([isActive, isFeatured])
}

model ProductTranslation {
  id          String   @id @default(cuid())
  productId   String
  product     Product  @relation(fields: [productId], references: [id], onDelete: Cascade)
  locale      Locale
  name        String
  slug        String
  description String?
  shortDesc   String?

  @@unique([productId, locale])
  @@index([slug, locale])
}

model ProductVariant {
  id         String   @id @default(cuid())
  productId  String
  product    Product  @relation(fields: [productId], references: [id], onDelete: Cascade)
  sku        String   @unique
  priceDelta Decimal  @default(0) @db.Decimal(12, 2) // delta sobre basePrice
  stock      Int      @default(0)
  options    Json     // { "color": "red", "size": "M" }
  isActive   Boolean  @default(true)
}

model ProductImage {
  id        String  @id @default(cuid())
  productId String
  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)
  url       String
  alt       String?
  position  Int     @default(0)
  isPrimary Boolean @default(false)
}

model ProductAttribute {
  id        String  @id @default(cuid())
  productId String
  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)
  key       String
  value     String
}

model Tag {
  id       String       @id @default(cuid())
  slug     String       @unique
  products ProductTag[]
}

model ProductTag {
  productId String
  tagId     String
  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)
  tag       Tag     @relation(fields: [tagId], references: [id], onDelete: Cascade)
  @@id([productId, tagId])
}

// ═══════════════════════════════════════════
// CARRITO Y ÓRDENES
// ═══════════════════════════════════════════
model Cart {
  id        String     @id @default(cuid())
  userId    String?    @unique
  sessionId String?    @unique
  currency  Currency   @default(USD)
  items     CartItem[]
  couponId  String?
  createdAt DateTime   @default(now())
  updatedAt DateTime   @updatedAt
}

model CartItem {
  id        String          @id @default(cuid())
  cartId    String
  cart      Cart            @relation(fields: [cartId], references: [id], onDelete: Cascade)
  productId String
  product   Product         @relation(fields: [productId], references: [id])
  variantId String?
  variant   ProductVariant? @relation(fields: [variantId], references: [id])
  quantity  Int             @default(1)
  @@unique([cartId, productId, variantId])
}

model Order {
  id              String         @id @default(cuid())
  orderNumber     String         @unique
  userId          String
  user            User           @relation(fields: [userId], references: [id])
  vendorId        String?
  vendor          Vendor?        @relation(fields: [vendorId], references: [id])
  status          OrderStatus    @default(PENDING)
  paymentStatus   PaymentStatus  @default(PENDING)
  subtotal        Decimal        @db.Decimal(12, 2)
  tax             Decimal        @db.Decimal(12, 2)
  shipping        Decimal        @db.Decimal(12, 2)
  discount        Decimal        @default(0) @db.Decimal(12, 2)
  total           Decimal        @db.Decimal(12, 2)
  currency        Currency       @default(USD)
  fxRate          Decimal        @default(1) @db.Decimal(10, 6) // tipo de cambio aplicado
  locale          Locale         @default(en)
  country         String         @default("US")
  shippingAddress Json
  billingAddress  Json?
  notes           String?
  paymentId       String?
  metadata        Json?
  items           OrderItem[]
  events          OrderEvent[]
  createdAt       DateTime       @default(now())
  updatedAt       DateTime       @updatedAt

  @@index([userId])
  @@index([vendorId])
  @@index([status])
  @@index([createdAt])
}

model OrderItem {
  id          String   @id @default(cuid())
  orderId     String
  order       Order    @relation(fields: [orderId], references: [id], onDelete: Cascade)
  productId   String
  product     Product  @relation(fields: [productId], references: [id])
  variantId   String?
  vendorId    String?
  name        String
  sku         String
  image       String?
  quantity    Int
  price       Decimal  @db.Decimal(12, 2)
  vendorShare Decimal  @db.Decimal(12, 2) // cuánto se lleva el vendor

  @@index([vendorId])
