### `apps/web/src/app/[locale]/product/[slug]/page.tsx` (Universal)

```tsx
import { api } from '@/lib/api';
import { notFound } from 'next/navigation';
import { getTranslations, unstable_setRequestLocale } from 'next-intl/server';
import { ProductGallery } from '@/components/product/ProductGallery';
import { ProductInfo } from '@/components/product/ProductInfo';
import { AddToCartButton } from '@/components/product/AddToCartButton';
import { ProductTabs } from '@/components/product/ProductTabs';
import { Breadcrumbs } from '@/components/ui/Breadcrumbs';

export default async function ProductPage({
  params: { slug, locale },
}: {
  params: { slug: string; locale: string };
}) {
  unstable_setRequestLocale(locale);
  const t = await getTranslations('product');

  let product;
  try {
    const { data } = await api.get(`/products/${slug}?locale=${locale}`);
    product = data.data;
  } catch {
    notFound();
  }

  const jsonLd = {
    '@context': 'https://schema.org',
    '@type': 'Product',
    name: product.name,
    image: product.images?.map((i: any) => i.url),
    description: product.description,
    sku: product.sku,
    offers: {
      '@type': 'Offer',
      price: product.price,
      priceCurrency: product.currency,
      availability: product.stock > 0
        ? 'https://schema.org/InStock'
        : 'https://schema.org/OutOfStock',
    },
  };

  return (
    <div className="container mx-auto px-4 py-8">
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
      />

      <Breadcrumbs items={[
        { label: 'Home', href: '/' },
        { label: product.category?.name },
        { label: product.name },
      ]} />

      <div className="grid md:grid-cols-2 gap-8 mt-6">
        <ProductGallery images={product.images} />
        <div className="space-y-6">
          <ProductInfo product={product} />
          <AddToCartButton product={product} />
          <p className="text-sm text-muted-foreground">
            {product.stock > 0 ? t('inStock', { count: product.stock }) : t('outOfStock')}
          </p>
        </div>
      </div>

      <ProductTabs
        description={product.description}
        attributes={product.attributes}
        reviews={product.reviews}
      />
    </div>
  );
}
